#!/usr/bin/env python3
"""Refresh the Java pack icons from the plugin's own 256x256 icon export."""

import argparse
import importlib.util
from pathlib import Path

SPEC = importlib.util.spec_from_file_location("bedrock_packs", Path(__file__).with_name("bedrock-packs.py"))
packs = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(packs)

# Generated by scripts/export-icons.mjs from docs/assets/icon-master.svg.
SOURCE = "docs/assets/icon-256.png"


def icon_bytes(root):
    contents = (root / SOURCE).read_bytes()
    width, height, _ = packs.read_png(contents)
    if (width, height) != (256, 256):
        raise ValueError(f"pack icon requires a 256x256 {SOURCE}")
    return contents


def sync(root, check=False):
    contents = icon_bytes(root)
    stale = []
    for variant in packs.java.VARIANTS:
        file = root / f"resourcepack/java/{variant}/pack.png"
        if check:
            if not file.is_file() or file.read_bytes() != contents:
                stale.append(str(file.relative_to(root)))
        else:
            file.write_bytes(contents)
    if stale:
        raise ValueError(f"pack icons differ from {SOURCE}; run sync-pack-icons.py: " + ", ".join(stale))


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    sync(packs.ROOT, parser.parse_args().check)
    print(f"OK: pack icons match {SOURCE}")
